# Rebuild xinput1_3.dll from source (no MSVC needed).  Requires Python:  pip install ziglang==0.13.0.post1
Set-Location $PSScriptRoot
python -m ziglang cc -target x86_64-windows-gnu -shared -O2 -Wall -Wextra -o xinput1_3.dll citw_trainer.c xinput1_3.def -luser32 -lgdi32
if ($LASTEXITCODE -eq 0) { Write-Host "built $PSScriptRoot\xinput1_3.dll - copy it over ..\xinput1_3.dll to use it with install.ps1" }
# hooks_gen.h is generated by genhooks.py from the game's PDB (maintainer tool, not needed to rebuild).
